/* ---------- Stepper ---------- */
/* the agent walks you through setup in the chat: no container; with .panel it becomes a card */
.stx{padding:16px 0;display:flex;flex-direction:column;gap:16px}
.stx.panel{padding:16px}
.stx-track{display:flex;align-items:center;gap:0}
.stx-st{display:flex;align-items:center;gap:8px;font-size:12.5px;color:var(--muted);white-space:nowrap;transition:color .3s}
.stx-st .n{width:24px;height:24px;border-radius:50%;display:grid;place-items:center;font-size:11.5px;font-weight:500;box-shadow:inset 0 0 0 1.5px var(--line);color:var(--muted);transition:background .35s var(--ease),box-shadow .35s,color .35s;flex:none}
.stx-st.on{color:var(--fg)}
.stx-st.on .n{box-shadow:inset 0 0 0 1.5px var(--accent),0 0 0 4px var(--accent-bg);color:var(--accent)}
.stx-st.done{color:var(--fg2);cursor:pointer}
.stx-st.done .n{background:var(--accent);box-shadow:none;color:#fff}
.stx-ln{flex:1;height:2px;margin:0 10px;border-radius:1px;background:var(--line);position:relative;overflow:hidden;min-width:16px}
.stx-ln i{position:absolute;inset:0;background:var(--accent);transform:scaleX(0);transform-origin:left;transition:transform .5s var(--ease)}
.stx-ln.full i{transform:none}
@media (max-width:520px){.stx-st .lb{display:none}.stx-st.on .lb{display:inline}}
.stx-vp{overflow:hidden;min-height:150px}
.stx-body{display:flex;flex-direction:column;gap:10px}
.stx-body.inr{animation:stxr .45s var(--ease) both}.stx-body.inl{animation:stxl .45s var(--ease) both}
@keyframes stxr{from{opacity:0;transform:translateX(24px);filter:blur(4px)}}
@keyframes stxl{from{opacity:0;transform:translateX(-24px);filter:blur(4px)}}
.stx-body h4{margin:0;font-size:14.5px;font-weight:500}
.stx-body p{margin:0;font-size:12.5px;color:var(--muted)}
.stx-opts{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}
@media (max-width:520px){.stx-opts{grid-template-columns:1fr}}
.stx-o{padding:12px;border-radius:12px;background:var(--chip);text-align:left;font-size:13px;display:flex;flex-direction:column;gap:4px;transition:background .2s,box-shadow .25s}
.stx-o span{font-size:11.5px;color:var(--muted)}
.stx-o:hover{background:var(--hover)}
.stx-o.on{background:var(--surface);box-shadow:inset 0 0 0 1.5px var(--accent)}
.stx-f{display:flex;justify-content:space-between}
.stx-bk[disabled]{visibility:hidden}
.stx-dn{display:flex;flex-direction:column;align-items:center;gap:6px;padding:18px 0;text-align:center;font-size:13px}
.stx-dn>svg{width:30px;height:30px;color:var(--ok)}

DM.def('stepper', (r, c) => {
  const S = [
    ['Workspace','Name your workspace','This is what your team will see.',[['Studio','Small team'],['Agency','Many clients'],['In-house','One product']]],
    ['Agent','How should the agent work?','You can change this any time.',[['Ask first','Safest'],['Balanced','Recommended'],['Autopilot','Fastest']]],
    ['Connect','Where do your designs live?','Pick one to start.',[['Figma','Frames and tokens'],['GitHub','Code and PRs'],['Both','Full loop']]]
  ];
  const track = $('.stx-track', r), body = $('.stx-body', r), bk = $('.stx-bk', r), nx = $('.stx-nx', r);
  let cur = 0, pick = [0, 1, 2];
  track.innerHTML = S.map((s, i) => `<div class="stx-st" data-i="${i}"><span class="n">${i + 1}</span><span class="lb">${s[0]}</span></div>` + (i < S.length - 1 ? '<div class="stx-ln"><i></i></div>' : '')).join('');
  const sts = $$('.stx-st', track), lns = $$('.stx-ln', track);
  function show(i, dir){
    cur = i; sts.forEach((s, j) => { s.classList.toggle('on', j === i); s.classList.toggle('done', j < i); $('.n', s).innerHTML = j < i ? I('check','xs') : j + 1; });
    lns.forEach((l, j) => l.classList.toggle('full', j < i));
    if (i >= S.length){ body.innerHTML = `<div class="stx-dn">${I('ok')}<b>You're set up</b><span class="muted">${S.map((s, k) => s[3][pick[k]][0]).join(' · ')}</span></div>`; bk.disabled = false; nx.textContent = 'Start over'; }
    else { const s = S[i]; body.innerHTML = `<h4>${s[1]}</h4><p>${s[2]}</p><div class="stx-opts">${s[3].map((o, k) => `<button class="stx-o${pick[i] === k ? ' on' : ''}" data-k="${k}"><b style="font-weight:500">${o[0]}</b><span>${o[1]}</span></button>`).join('')}</div>`;
      $$('.stx-o', body).forEach(b => b.onclick = () => { pick[i] = +b.dataset.k; $$('.stx-o', body).forEach(x => x.classList.toggle('on', x === b)); });
      bk.disabled = i === 0; nx.textContent = i === S.length - 1 ? 'Finish' : 'Continue'; }
    if (dir){ body.classList.remove('inr','inl'); void body.offsetWidth; body.classList.add(dir > 0 ? 'inr' : 'inl'); }
  }
  nx.onclick = () => cur >= S.length ? show(0, -1) : show(cur + 1, 1);
  bk.onclick = () => show(Math.max(0, cur - 1), -1);
  sts.forEach((s, i) => s.onclick = () => { if (i < cur) show(i, -1); });
  show(0);
});
